import os, json, re

session_file = os.environ['RLM_SESSION_DIR'] + '/../../sessions/' + os.path.basename(os.environ['RLM_SESSION_DIR']) + '.jsonl'
with open(session_file) as f:
    content = f.read()

content_decoded = content.replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \(([\d]+)x([\d]+)\):\n([0-9\s\n]+?)(?=\n[A-Z]|\Z)', content_decoded):
    key = m.group(1).strip() + ' (' + m.group(2) + 'x' + m.group(3) + ')'
    h, w = int(m.group(2)), int(m.group(3))
    grid_text = m.group(4)
    rows = [re.sub(r'\s+', ' ', row).split(' ') for row in grid_text.strip().split('\n')[:h]]
    clean_grid = []
    for r in rows:
        r = [int(x) for x in r if x.isdigit()]
        while len(r) < 30:
            r.append(0)
        clean_grid.append(r[:w])
    G[key] = clean_grid

demo1_in = G['Demo pair 1 input (10x19)']
demo1_out = G['Demo pair 1 output (2x3)']
demo2_in = G['Demo pair 2 input (10x10)']
demo2_out = G['Demo pair 2 output (2x3)']

def check_transformation(in_grid, out_grid, base_r=0, base_c=0, r_step=0, c_step=0):
    """Check if out_grid[i][j] equals in_grid[base_r + j*r_step][base_c + i*c_step]"""
    if base_r >= len(in_grid) or base_c >= len(in_grid[0]):
        return False
    for i in range(len(out_grid)):
        for j in range(len(out_grid[0])):
            try:
                val = in_grid[base_r + j * r_step][base_c + i * c_step]
            except:
                return False
            if val != out_grid[i][j]:
                return False
    return True

